            "metric_name": "rank/width",
            "metric_value": ratio,
            "instances_tested": 1,
            "conjecture_holds": False,
            "counterexample": f"ratio={ratio}, expected_ratio={expected_ratio}"
        }

if __name__ == "__main__":
